refentry.refsect1:
&reftitle.parameters;
request
Una instancia de Yaf_Request_Abstract a despachar.

  &reftitle.examples;

   Ejemplo de Yaf_Dispatcher::dispatch


<?php
$app = new Yaf_Application(dirname(__FILE__) . "/conf/application.ini");
$app->bootstrap();

// Se construye una petición que apunta a ProductController::detailAction y
// se despacha manualmente.
$request = new Yaf_Request_Http("/product/detail/id/42");

$response = Yaf_Dispatcher::getInstance()->dispatch($request);

if ($response instanceof Yaf_Response_Abstract) {
    $response->response();
}
?>
